// ─── File: .../service/ReadCommittedValuationService.java ───
// READ_COMMITTED: each query sees latest committed data.
// RISK: between reading balance and holdings, another TX may commit a deposit.
// Balance read = old value, but holdings read = new state. INCONSISTENT!
package com.bank.valuation.service;

import com.bank.valuation.dto.PortfolioValuation;
import com.bank.valuation.model.*;
import com.bank.valuation.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class ReadCommittedValuationService {

    private final AccountRepository accountRepo;
    private final HoldingRepository holdingRepo;

    /**
     * READ_COMMITTED (PostgreSQL default):
     * - Each SELECT sees the latest COMMITTED data at the time of THAT query.
     * - If another TX commits a deposit between our balance read and holdings read,
     *   we get INCONSISTENT data (old balance + new holdings).
     * - This is a NON-REPEATABLE READ.
     */
    @Transactional(isolation = Isolation.READ_COMMITTED, readOnly = true)
    public PortfolioValuation calculateValuation(String accountId) {
        log.info("[READ_COMMITTED] Reading balance...");
        Account account = accountRepo.findById(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + accountId));
        BigDecimal cashBalance = account.getBalance();

        // *** DANGER ZONE: another TX could commit a deposit RIGHT HERE ***
        // If it does, our next read sees the NEW committed data — but balance is OLD.

        log.info("[READ_COMMITTED] Reading holdings (balance may be stale now)...");
        List<Holding> holdings = holdingRepo.findByAccountId(accountId);
        BigDecimal holdingsValue = holdings.stream()
            .map(Holding::getMarketValue)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new PortfolioValuation(accountId, cashBalance, holdingsValue,
            cashBalance.add(holdingsValue), "READ_COMMITTED",
            holdings.stream().map(h -> h.getSymbol() + "=" + h.getMarketValue()).toList());
    }
}
