package com.bank.valuation.controller;

import com.bank.valuation.dto.PortfolioValuation;
import com.bank.valuation.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/valuation")
@RequiredArgsConstructor
public class ValuationController {

    private final ReadCommittedValuationService readCommittedService;
    private final RepeatableReadValuationService repeatableReadService;

    @GetMapping("/{accountId}/read-committed")
    public PortfolioValuation readCommitted(@PathVariable String accountId) {
        return readCommittedService.calculateValuation(accountId);
    }

    @GetMapping("/{accountId}/repeatable-read")
    public PortfolioValuation repeatableRead(@PathVariable String accountId) {
        return repeatableReadService.calculateValuation(accountId);
    }
}
