package com.bank.valuation.service;

import com.bank.valuation.dto.PortfolioValuation;
import com.bank.valuation.model.*;
import com.bank.valuation.repository.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class ValuationServiceTest {

    @Mock AccountRepository accountRepo;
    @Mock HoldingRepository holdingRepo;
    @InjectMocks RepeatableReadValuationService service;

    @Test
    void shouldCalculateConsistentPortfolioValue() {
        Account account = mock(Account.class);
        when(account.getBalance()).thenReturn(new BigDecimal("500000"));
        when(accountRepo.findById("SAV2001")).thenReturn(Optional.of(account));

        Holding h1 = mock(Holding.class);
        when(h1.getMarketValue()).thenReturn(new BigDecimal("245050"));
        when(h1.getSymbol()).thenReturn("RELIANCE");
        when(holdingRepo.findByAccountId("SAV2001")).thenReturn(List.of(h1));

        PortfolioValuation result = service.calculateValuation("SAV2001");

        assertThat(result.cashBalance()).isEqualByComparingTo("500000");
        assertThat(result.holdingsValue()).isEqualByComparingTo("245050");
        assertThat(result.totalPortfolioValue()).isEqualByComparingTo("745050");
        assertThat(result.isolationLevel()).isEqualTo("REPEATABLE_READ");
    }
}
